public record PriceList(List<PriceRule> rules) {
    public PriceList {
        rules = List.copyOf(rules);                 // bất biến: không ai sửa được bản trong cache
    }

    public PriceList forCustomer(Customer customer) {
        return new PriceList(rules.stream().filter(rule -> rule.appliesTo(customer)).toList());
    }
}

@Service
class CheckoutService {
    Money quote(Customer customer, Cart cart) {
        PriceList list = pricingService.priceList(customer.region()).forCustomer(customer);   // bản mới
        return list.apply(cart);
    }
}
